python3 - <<'PY'
from pathlib import Path
p = Path('crates/printer/src/util.rs')
s = p.read_text()
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if is_multi_line && m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            // Preserve unmatched bytes, but not the look-ahead context.
            let end = std::cmp::min(range.end, subject.len());
            dst.extend_from_slice(&subject[last_match..end]);
'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
p = Path('CHANGELOG.md')
s = p.read_text()
needle = 'Bug fixes:\n\n'
assert s.startswith('13.0.1\n')
s = s.replace(needle, needle + '* Fix multiline replacements including content beyond the matching lines.\n', 1)
p.write_text(s)
PY
