python3 - <<'PY'
import subprocess
haystack = '''# Compile requirements.txt files from all found or specified requirements.in files (compile).
# Use -h to include hashes, -u dep1,dep2... to upgrade specific dependencies, and -U to upgrade all.
pipc () {  # [-h] [-U|-u <pkgspec>[,<pkgspec>...]] [<reqs-in>...] [-- <pip-compile-arg>...]
    emulate -L zsh
    unset REPLY
    if [[ $1 == --help ]] { zpy $0; return }
    [[ $ZPY_PROCS ]] || return

    local gen_hashes upgrade upgrade_csv
    while [[ $1 == -[hUu] ]] {
        if [[ $1 == -h ]] { gen_hashes=--generate-hashes; shift   }
        if [[ $1 == -U ]] { upgrade=1;                    shift   }
        if [[ $1 == -u ]] { upgrade=1; upgrade_csv=$2;    shift 2 }
    }
}
'''
pattern = r'^(?P<predoc>\n?(# .*\n)*)(alias (?P<aname>pipc)="[^"]+"|(?P<fname>pipc) \(\) \{)(  #(?P<usage> .+))?'
expected = ' [-h] [-U|-u <pkgspec>[,<pkgspec>...]] [<reqs-in>...] [-- <pip-compile-arg>...]\n'
for engine in ('default', 'pcre2'):
    args = ['target/debug/rg', '--no-config', '--color', 'never', '-NU', '--engine', engine, '-r', '$usage', pattern]
    result = subprocess.run(args, input=haystack, text=True, capture_output=True, check=True)
    assert result.stdout == expected, (engine, result.stdout)
    print(f'{engine}: reported reproduction produces only the expected usage line')
for engine in ('default', 'pcre2'):
    args = ['target/debug/rg', '--no-config', '--engine', engine, '-r', 'X', 'a*']
    result = subprocess.run(args, input='b', text=True, capture_output=True, check=True)
    assert result.stdout == 'XbX\n', (engine, result.stdout)
print('Single-line empty matches at EOF retain their existing behavior')
PY

